#!/usr/bin/env python3
# generated by stage x4 source-preserving extraction; original methods unchanged
from __future__ import annotations
from PyQt6.QtCore import Qt
from PyQt6.QtGui import QColor, QFont, QFontDatabase, QTextCursor, QTextDocument

MAX_SEARCH_MATCHES = 10_000
MAX_SEARCH_QUERY_CHARACTERS = 4096


class WindowSearchViewMixin:

    def _source_font_for_zoom(self) -> QFont:
        fixed = QFontDatabase.systemFont(QFontDatabase.SystemFont.FixedFont)
        family = str(self.settings.get("editor_font_family", "") or "").strip() or fixed.family()
        size = max(6, min(72, int(self.settings.get("editor_font_size", 11))))
        weight = max(100, min(900, int(self.settings.get("editor_font_weight", 400))))
        font = QFont(family)
        font.setPointSizeF(max(6.0, size * self.zoom_percent / 100.0))
        font.setStyleHint(QFont.StyleHint.Monospace)
        try:
            font.setWeight(QFont.Weight(weight))
        except (TypeError, ValueError):
            font.setWeight(QFont.Weight.Normal)
        font.setItalic(bool(self.settings.get("editor_font_italic", False)))
        return font

    def set_view_mode(self, mode: str, *, persist: bool = True) -> None:
        if mode not in {"source", "split", "preview"}: mode = "split"
        if getattr(self, "view_mode", "split") == "split" and hasattr(self, "splitter"):
            sizes = self.splitter.sizes()
            if len(sizes) == 2 and all(int(v) > 0 for v in sizes): self._last_splitter_sizes = [int(v) for v in sizes]
        self.view_mode = mode
        if mode in {"source", "split"}:
            self.last_editable_view_mode = mode
        self.editor.setVisible(mode in {"source", "split"}); self.preview.setVisible(mode in {"split", "preview"})
        self.source_only_action.setChecked(mode == "source"); self.split_action.setChecked(mode == "split"); self.preview_only_action.setChecked(mode == "preview")
        if mode == "split":
            self._active_text_surface = "source"
            self.splitter.setSizes(getattr(self, "_last_splitter_sizes", [3, 2])); self.schedule_preview(); self.editor.setFocus()
        elif mode == "preview":
            self._active_text_surface = "preview"
            self.schedule_preview(); self.preview.setFocus()
        else:
            self._active_text_surface = "source"
            self.editor.setFocus()
        self._update_ui_state()
        if persist and hasattr(self, "settings"): self.persist_preferences()

    def _focus_current_view(self) -> None:
        """Keep keyboard focus aligned with the persisted viewing layout."""
        if self.view_mode == "preview":
            self.preview.setFocus()
        else:
            self.editor.setFocus()

    def toggle_word_wrap(self, checked: bool) -> None:
        self.editor.set_word_wrap_enabled(bool(checked)); self.persist_preferences()

    def toggle_line_numbers(self, checked: bool) -> None:
        self.editor.set_line_numbers_visible(bool(checked)); self.persist_preferences()

    def set_zoom(self, percent: int, *, persist=True) -> None:
        self.zoom_percent = max(50, min(300, int(percent)))
        def apply() -> None:
            self.editor.set_editor_font(self._source_font_for_zoom())
            self._apply_preview_font()
            self.update_status()
        self._apply_presentation_safely(apply)
        if persist:
            self.persist_preferences()

    def adjust_zoom_from_wheel(self, delta: int) -> None:
        if delta > 0:
            self.set_zoom(self.zoom_percent + 10)
        elif delta < 0:
            self.set_zoom(self.zoom_percent - 10)

    def toggle_find_panel(self, replace: bool = False) -> bool:
        target = self.find_panel.replace_edit if replace else self.find_panel.find_edit
        if self.find_panel.isVisible() and target.hasFocus():
            self.hide_find_panel()
            return False
        self.show_find_panel(replace)
        return True

    def show_find_panel(self, replace: bool = False) -> None:
        self.find_panel.show()
        selected = self.editor.textCursor().selectedText().replace("\u2029", "\n")
        if selected and "\n" not in selected and len(selected) <= MAX_SEARCH_QUERY_CHARACTERS:
            self.find_panel.find_edit.setText(selected)
        self.find_panel.find_edit.setFocus(Qt.FocusReason.ShortcutFocusReason)
        self.find_panel.find_edit.selectAll()
        if replace:
            self.find_panel.replace_edit.setFocus(Qt.FocusReason.ShortcutFocusReason)
            self.find_panel.replace_edit.selectAll()
        self.refresh_search()

    def hide_find_panel(self) -> None:
        if not hasattr(self, "find_panel") or not self.find_panel.isVisible():
            return
        self.find_panel.hide()
        self.clear_search_results()
        self._focus_current_view()

    def _replace_flags(self):
        flags = QTextDocument.FindFlag(0)
        if self.find_panel.case_box.isChecked():
            flags |= QTextDocument.FindFlag.FindCaseSensitively
        return flags

    def _selection_matches_replace_query(self, cursor: QTextCursor, query: str) -> bool:
        if not cursor.hasSelection():
            return False
        selected = cursor.selectedText().replace("\u2029", "\n")
        if self.find_panel.case_box.isChecked():
            return selected == query
        return selected.casefold() == query.casefold()

    def clear_search_results(self) -> None:
        self._search_matches = []
        self._current_search_index = -1
        self._search_results_truncated = False
        self.editor.clear_search_selections()
        self._update_search_counter()

    def _update_search_counter(self) -> None:
        total = len(self._search_matches)
        current = self._current_search_index + 1 if 0 <= self._current_search_index < total else 0
        total_text = f"{total:,}+" if self._search_results_truncated else f"{total:,}"
        self.find_panel.count_label.setText(f"{current:,}/{total_text}")
        self.find_panel.count_label.setToolTip(
            f"Showing the first {MAX_SEARCH_MATCHES:,} matches." if self._search_results_truncated else ""
        )
        enabled = total > 0
        self.find_panel.previous_button.setEnabled(enabled)
        self.find_panel.next_button.setEnabled(enabled)

    def refresh_search(self, _value=None) -> bool:
        """Highlight all matches in gold and keep the active result as a real selection."""
        if not hasattr(self, "find_panel") or not self.find_panel.isVisible():
            return False
        query = self.find_panel.find_edit.text()[:MAX_SEARCH_QUERY_CHARACTERS]
        self._search_matches = []
        self._current_search_index = -1
        self._search_results_truncated = False
        if not query:
            self.editor.clear_search_selections()
            self._update_search_counter()
            return False
        document = self.editor.document()
        cursor = QTextCursor(document)
        flags = self._replace_flags()
        while len(self._search_matches) < MAX_SEARCH_MATCHES:
            found = document.find(query, cursor, flags)
            if found.isNull():
                break
            self._search_matches.append((found.selectionStart(), found.selectionEnd()))
            cursor = QTextCursor(found)
            cursor.setPosition(found.selectionEnd())
        if len(self._search_matches) == MAX_SEARCH_MATCHES:
            self._search_results_truncated = not document.find(query, cursor, flags).isNull()
        selections = []
        for start, end in self._search_matches:
            selection = self.editor._selection_for_range(start, end)
            selection.format.setBackground(QColor("#C9A227"))
            selection.format.setForeground(QColor("#101010"))
            selections.append(selection)
        self.editor.set_search_selections(selections)
        if self._search_matches:
            self._current_search_index = 0
            start, end = self._search_matches[0]
            active_cursor = self.editor.textCursor()
            active_cursor.setPosition(start)
            active_cursor.setPosition(end, QTextCursor.MoveMode.KeepAnchor)
            self.editor.setTextCursor(active_cursor)
            self.editor.ensureCursorVisible()
        self._update_search_counter()
        return bool(self._search_matches)

    def _ensure_search_matches(self) -> bool:
        if not self.find_panel.isVisible():
            self.show_find_panel(False)
        if not self.find_panel.find_edit.text():
            self.find_panel.find_edit.setFocus(Qt.FocusReason.ShortcutFocusReason)
            self.find_panel.find_edit.selectAll()
            return False
        if not self._search_matches:
            return self.refresh_search()
        return True

    def _jump_search(self, step: int) -> bool:
        if not self._ensure_search_matches():
            return False
        if self._current_search_index < 0:
            self._current_search_index = 0 if step > 0 else len(self._search_matches) - 1
        else:
            self._current_search_index = (self._current_search_index + step) % len(self._search_matches)
        start, end = self._search_matches[self._current_search_index]
        cursor = self.editor.textCursor()
        cursor.setPosition(start)
        cursor.setPosition(end, QTextCursor.MoveMode.KeepAnchor)
        self.editor.setTextCursor(cursor)
        self.editor.ensureCursorVisible()
        self._update_search_counter()
        return True

    def find_next(self) -> bool:
        return self._jump_search(1)

    def find_previous(self) -> bool:
        return self._jump_search(-1)

    def replace_one(self) -> bool:
        if self.editor.isReadOnly() or self.view_mode == "preview":
            return False
        query = self.find_panel.find_edit.text()[:MAX_SEARCH_QUERY_CHARACTERS]
        if not query:
            self.find_panel.find_edit.setFocus()
            return False
        cursor = self.editor.textCursor()
        if not self._selection_matches_replace_query(cursor, query):
            if not self.find_next():
                return False
            cursor = self.editor.textCursor()
        if not cursor.hasSelection():
            return False
        replacement = self.find_panel.replace_edit.text()
        document_length = max(0, self.editor.document().characterCount() - 1)
        selected_length = abs(cursor.selectionEnd() - cursor.selectionStart())
        if document_length - selected_length + len(replacement) > self.editor.MAX_DOCUMENT_CHARACTERS:
            self.statusBar().showMessage(
                "The replacement would exceed MaqaronyPad's source document safety limit.", 5000
            )
            return False
        cursor.insertText(replacement)
        self.editor.setTextCursor(cursor)
        self.refresh_search()
        return True

    def replace_all(self) -> int:
        if self.editor.isReadOnly() or self.view_mode == "preview":
            return 0
        query = self.find_panel.find_edit.text()[:MAX_SEARCH_QUERY_CHARACTERS]
        if not query:
            self.find_panel.find_edit.setFocus()
            return 0
        replacement = self.find_panel.replace_edit.text()
        document = self.editor.document()
        flags = self._replace_flags()

        scan = QTextCursor(document)
        count = 0
        while count <= MAX_SEARCH_MATCHES:
            match = document.find(query, scan, flags)
            if match.isNull():
                break
            count += 1
            scan = QTextCursor(match)
            scan.setPosition(match.selectionEnd())
        if count > MAX_SEARCH_MATCHES:
            self.statusBar().showMessage(
                f"Replace All is limited to {MAX_SEARCH_MATCHES:,} matches.", 5000
            )
            return 0
        if not count:
            self.refresh_search()
            return 0
        current_length = max(0, document.characterCount() - 1)
        resulting_length = current_length + count * (len(replacement) - len(query))
        if resulting_length > self.editor.MAX_DOCUMENT_CHARACTERS:
            self.statusBar().showMessage(
                "Replace All would exceed MaqaronyPad's source document safety limit.", 5000
            )
            return 0

        scan = QTextCursor(document)
        edit_cursor = QTextCursor(document)
        replaced = 0
        self._search_refresh_suspended = True
        edit_cursor.beginEditBlock()
        try:
            while replaced < count:
                match = document.find(query, scan, flags)
                if match.isNull():
                    break
                match.insertText(replacement)
                scan = QTextCursor(match)
                replaced += 1
        finally:
            edit_cursor.endEditBlock()
            self._search_refresh_suspended = False
        self.statusBar().showMessage(f"Replaced {replaced} occurrence(s).", 3000)
        self.refresh_search()
        return replaced

